pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title BallXP Token
 * @dev An ERC20 token used for staking and rewards within the Web3 Bouncing Balls ecosystem.
 * This contract is deployed by the main Web3BouncingBalls contract.
 */
contract BallXP is ERC20, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    constructor() ERC20("Ball Experience Token", "BXP") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
    }

    /**
     * @dev Creates a new amount of tokens and assigns them to an account.
     * Can only be called by an account with the MINTER_ROLE.
     */
    function mint(address to, uint256 amount) public onlyRole(MINTER_ROLE) {
        _mint(to, amount);
    }
}

/**
 * @title Web3 Bouncing Balls
 * @dev A comprehensive smart contract for a blockchain-based physics game.
 * It includes an ERC721 NFT system for "Balls", an in-game XP and leveling system,
 * PvP arenas, a marketplace, breeding mechanics, and a staking system using the BallXP token.
 */
contract Web3BouncingBalls is ERC721, ERC721Enumerable, AccessControl, Pausable, ReentrancyGuard {

    // Using OZ Counters for safe ID incrementing
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIdCounter;
    Counters.Counter private _arenaIdCounter;

    //---------------------------------------------------------
    // Roles
    //---------------------------------------------------------
    bytes32 public constant GAME_ADMIN_ROLE = keccak256("GAME_ADMIN_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    //---------------------------------------------------------
    // Structs & Enums
    //---------------------------------------------------------

    /// @dev Enum for upgrading a specific trait of a Ball.
    enum Trait { Mass, Elasticity, Power }

    /// @dev Core data structure for each Ball NFT.
    struct Ball {
        uint32 mass;
        uint32 elasticity; // 0-100
        uint32 power;
        uint32 color;      // e.g., 0xFF0000 for red
        uint16 level;
        uint16 breedCount;
        uint64 xp;         // Experience points for leveling up
        uint64 totalCollisions;
        uint64 wins;
        uint64 losses;
        uint64 lastBredTimestamp;
    }

    /// @dev Enum for the state of a PvP Arena.
    enum ArenaState { Open, InProgress, AwaitingResult, Closed }

    /// @dev Data structure for a PvP battle arena.
    struct Arena {
        uint256 id;
        ArenaState state;
        uint256 entryFee;
        uint256 prizePool;
        uint8 minPlayers;
        uint8 maxPlayers;
        address[] players;
    }

    /// @dev Data structure for a marketplace listing.
    struct Listing {
        address seller;
        uint256 price;
    }

    //---------------------------------------------------------
    // State Variables
    //---------------------------------------------------------

    // --- Token Contracts ---
    BallXP public immutable bxpToken;

    // --- Mappings ---
    mapping(uint256 => Ball) private _balls;
    mapping(uint256 => Arena) private _arenas;
    mapping(uint256 => mapping(address => uint256)) private _arenaPlayerBallIds;
    mapping(uint256 => Listing) private _listings;
    mapping(address => uint256) public stakedBXP;
    mapping(uint256 => bool) private _ballLocked; // Tracks if a ball is in an arena, listed, etc.

    // --- Economic Parameters ---
    address public treasuryAddress;
    address public liquidityPoolAddress;

    uint256 public mintFee = 0.01 ether;
    uint256 public breedingFee = 0.01 ether;
    uint16 public marketplaceFeeBPS = 250; // 2.5%

    // --- Game Parameters ---
    uint256 public constant BREEDING_COOLDOWN = 7 days;
    uint16 public constant MAX_BREED_COUNT = 3;
    uint256 private _randomNonce;

    //---------------------------------------------------------
    // Events
    //---------------------------------------------------------
    event BallMinted(uint256 indexed tokenId, address indexed owner, uint32 mass, uint32 elasticity, uint32 power);
    event BallUpgraded(uint256 indexed tokenId, Trait trait, uint32 newValue);
    event BallLevelUp(uint256 indexed tokenId, uint16 newLevel);
    event XPEarned(uint256 indexed tokenId, uint64 xpGained);

    event ArenaCreated(uint256 indexed arenaId, uint256 entryFee, uint8 minPlayers, uint8 maxPlayers);
    event PlayerJoinedArena(uint256 indexed arenaId, address indexed player, uint256 tokenId);
    event GameStarted(uint256 indexed arenaId);
    event GameEnded(uint256 indexed arenaId, address indexed winner, uint256 prize, bytes32 replayHash);

    event BallListed(uint256 indexed tokenId, address indexed seller, uint256 price);
    event BallSold(uint256 indexed tokenId, address indexed seller, address indexed buyer, uint256 price);
    event ListingCancelled(uint256 indexed tokenId);

    event BallBred(uint256 indexed newBallId, uint256 indexed parentA, uint256 indexed parentB);

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event FeesWithdrawn(address indexed destination, uint256 amount, bool isTreasury);

    //---------------------------------------------------------
    // Custom Errors
    //---------------------------------------------------------
    error InvalidFee();
    error NotTokenOwner();
    error TokenNotApproved();
    error TokenNotFound();
    error NotForSale();
    error IncorrectPrice();
    error ArenaNotFound();
    error ArenaNotOpen();
    error ArenaFull();
    error AlreadyInArena();
    error InsufficientStake();
    error InvalidPlayerCount();
    error InvalidGameState();
    error NotEnoughXP();
    error BreedingCooldown();
    error MaxBreedsReached();
    error CannotBreedWithSelf();
    error BallIsLocked();
    error InsufficientBalance();
    error InvalidAmount();

    //---------------------------------------------------------
    // Constructor
    //---------------------------------------------------------

    /**
     * @dev Sets up the contract, creating the BallXP token and assigning initial roles.
     * The constructor is intentionally empty of arguments as per requirements.
     */
    constructor() ERC721("Bouncing Ball", "BALL") {
        bxpToken = new BallXP();

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(GAME_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);

        treasuryAddress = msg.sender;
        liquidityPoolAddress = msg.sender;

        bxpToken.grantRole(bxpToken.MINTER_ROLE(), address(this));
    }

    //---------------------------------------------------------
    // Overrides & Hooks
    //---------------------------------------------------------

    /**
     * @dev Hook that is called before any token transfer.
     * Used to prevent transfer of balls that are locked (listed on the marketplace or active in a game).
     */
    function _beforeTokenTransfer(address from, address to, uint256 firstTokenId, uint256 batchSize)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);
        if (from != address(0) && _ballLocked[firstTokenId]) {
            revert BallIsLocked();
        }
    }

    function _baseURI() internal pure override returns (string memory) {
        return "";
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    //---------------------------------------------------------
    // Pausable Functions
    //---------------------------------------------------------

    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    //---------------------------------------------------------
    // Admin Functions
    //---------------------------------------------------------

    function setMintFee(uint256 _fee) public onlyRole(DEFAULT_ADMIN_ROLE) { mintFee = _fee; }
    function setBreedingFee(uint256 _fee) public onlyRole(DEFAULT_ADMIN_ROLE) { breedingFee = _fee; }
    function setMarketplaceFee(uint16 _feeBPS) public onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_feeBPS > 1000) revert InvalidFee(); // Max 10%
        marketplaceFeeBPS = _feeBPS;
    }
    function setTreasuryAddress(address _address) public onlyRole(DEFAULT_ADMIN_ROLE) { treasuryAddress = _address; }
    function setLiquidityPoolAddress(address _address) public onlyRole(DEFAULT_ADMIN_ROLE) { liquidityPoolAddress = _address; }

    function withdraw(address payable to, uint256 amount, bool isTreasury) public onlyRole(DEFAULT_ADMIN_ROLE) {
        if(to != (isTreasury ? treasuryAddress : liquidityPoolAddress)) revert("Invalid destination");
        if (amount > address(this).balance) revert InsufficientBalance();
        (bool success, ) = to.call{value: amount}("");
        require(success, "Withdrawal failed");
        emit FeesWithdrawn(to, amount, isTreasury);
    }

    //---------------------------------------------------------
    // Ball NFT System (ERC721)
    //---------------------------------------------------------

    function mintBall() public payable whenNotPaused returns (uint256) {
        if (msg.value != mintFee) revert InvalidFee();

        _tokenIdCounter.increment();
        uint256 newItemId = _tokenIdCounter.current();

        uint256 randomSeed = _generateRandom(newItemId);
        _balls[newItemId] = Ball({
            mass: uint32(50 + (randomSeed % 51)), // 50-100
            elasticity: uint32(50 + ((randomSeed >> 8) % 51)), // 50-100
            power: uint32(50 + ((randomSeed >> 16) % 51)), // 50-100
            color: uint32(randomSeed >> 24),
            level: 1, breedCount: 0, xp: 0,
            totalCollisions: 0, wins: 0, losses: 0, lastBredTimestamp: 0
        });

        _safeMint(msg.sender, newItemId);
        emit BallMinted(newItemId, msg.sender, _balls[newItemId].mass, _balls[newItemId].elasticity, _balls[newItemId].power);
        return newItemId;
    }

    //---------------------------------------------------------
    // XP & Leveling System
    //---------------------------------------------------------

    function levelUp(uint256 tokenId, Trait traitToBoost) public whenNotPaused {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();

        Ball storage ball = _balls[tokenId];
        uint256 requiredXP = _xpRequiredForLevel(ball.level + 1);
        if (ball.xp < requiredXP) revert NotEnoughXP();

        ball.level++;

        if (traitToBoost == Trait.Mass) ball.mass += 10;
        else if (traitToBoost == Trait.Elasticity) ball.elasticity += 10;
        else if (traitToBoost == Trait.Power) ball.power += 10;

        emit BallLevelUp(tokenId, ball.level);
        emit BallUpgraded(tokenId, traitToBoost, traitToBoost == Trait.Mass ? ball.mass : (traitToBoost == Trait.Elasticity ? ball.elasticity : ball.power));
    }

    //---------------------------------------------------------
    // PvP Battle Arena
    //---------------------------------------------------------

    function createArena(uint256 entryFee, uint8 minPlayers, uint8 maxPlayers) public onlyRole(GAME_ADMIN_ROLE) {
        if(minPlayers < 2 || maxPlayers > 10 || minPlayers > maxPlayers) revert InvalidPlayerCount();
        _arenaIdCounter.increment();
        uint256 arenaId = _arenaIdCounter.current();

        Arena storage newArena = _arenas[arenaId];
        newArena.id = arenaId;
        newArena.state = ArenaState.Open;
        newArena.entryFee = entryFee;
        newArena.minPlayers = minPlayers;
        newArena.maxPlayers = maxPlayers;

        emit ArenaCreated(arenaId, entryFee, minPlayers, maxPlayers);
    }

    function joinArena(uint256 arenaId, uint256 tokenId) public payable whenNotPaused nonReentrant {
        Arena storage arena = _arenas[arenaId];
        if(arena.id == 0) revert ArenaNotFound();
        if(arena.state != ArenaState.Open) revert ArenaNotOpen();
        if(arena.players.length >= arena.maxPlayers) revert ArenaFull();
        if(ownerOf(tokenId) != msg.sender) revert NotTokenOwner();
        if (msg.value != arena.entryFee) revert InsufficientStake();
        if (_ballLocked[tokenId]) revert BallIsLocked();

        _arenaPlayerBallIds[arenaId][msg.sender] = tokenId;
        arena.players.push(msg.sender);
        arena.prizePool += msg.value;
        _ballLocked[tokenId] = true;

        emit PlayerJoinedArena(arenaId, msg.sender, tokenId);

        if (arena.players.length == arena.maxPlayers) {
            _startGame(arenaId);
        }
    }

    function forceStartArena(uint256 arenaId) public onlyRole(GAME_ADMIN_ROLE) {
        Arena storage arena = _arenas[arenaId];
        if (arena.state != ArenaState.Open) revert ArenaNotOpen();
        if (arena.players.length < arena.minPlayers) revert InvalidPlayerCount();
        _startGame(arenaId);
    }

    function submitGameResult(uint256 arenaId, address winner, uint64[] calldata collisionCounts, uint256[] calldata bxpRewards, bytes32 replayHash) public whenNotPaused onlyRole(GAME_ADMIN_ROLE) {
        Arena storage arena = _arenas[arenaId];
        if (arena.state != ArenaState.InProgress) revert InvalidGameState();
        if (arena.players.length != collisionCounts.length || arena.players.length != bxpRewards.length) revert("Mismatched array lengths");

        uint256 winnerPrize = (arena.prizePool * 70) / 100;
        uint256 liquidityPrize = (arena.prizePool * 20) / 100;

        _sendValue(payable(winner), winnerPrize);
        _sendValue(payable(liquidityPoolAddress), liquidityPrize);
        _sendValue(payable(treasuryAddress), arena.prizePool - winnerPrize - liquidityPrize);

        for (uint i = 0; i < arena.players.length; i++) {
            address player = arena.players[i];
            uint256 ballId = _arenaPlayerBallIds[arenaId][player];
            Ball storage ball = _balls[ballId];
            uint64 xpGain = collisionCounts[i] + (player == winner ? 10 : 0);
            ball.xp += xpGain;
            ball.totalCollisions += collisionCounts[i];
            if (player == winner) ball.wins++; else ball.losses++;

            _ballLocked[ballId] = false;

            if (bxpRewards[i] > 0) bxpToken.mint(player, bxpRewards[i]);
            emit XPEarned(ballId, xpGain);
        }

        arena.state = ArenaState.Closed;
        emit GameEnded(arenaId, winner, winnerPrize, replayHash);
    }

    //---------------------------------------------------------
    // Marketplace
    //---------------------------------------------------------

    function listBall(uint256 tokenId, uint256 price) public whenNotPaused {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();
        if (getApproved(tokenId) != address(this)) revert TokenNotApproved();
        if (price == 0) revert InvalidAmount();
        if (_ballLocked[tokenId]) revert BallIsLocked();

        _listings[tokenId] = Listing(msg.sender, price);
        _ballLocked[tokenId] = true;
        emit BallListed(tokenId, msg.sender, price);
    }

    function cancelListing(uint256 tokenId) public whenNotPaused {
        if (_listings[tokenId].seller != msg.sender) revert NotTokenOwner();
        delete _listings[tokenId];
        _ballLocked[tokenId] = false;
        emit ListingCancelled(tokenId);
    }

    function buyBall(uint256 tokenId) public payable whenNotPaused nonReentrant {
        Listing memory listing = _listings[tokenId];
        if (listing.price == 0) revert NotForSale();
        if (msg.value != listing.price) revert IncorrectPrice();

        delete _listings[tokenId];
        _ballLocked[tokenId] = false;

        uint256 fee = (msg.value * marketplaceFeeBPS) / 10000;
        uint256 sellerProceeds = msg.value - fee;

        _sendValue(payable(treasuryAddress), fee);
        _sendValue(payable(listing.seller), sellerProceeds);

        _transfer(listing.seller, msg.sender, tokenId);
        emit BallSold(tokenId, listing.seller, msg.sender, msg.value);
    }

    //---------------------------------------------------------
    // Breeding System
    //---------------------------------------------------------

    function breed(uint256 parentAId, uint256 parentBId) public payable whenNotPaused returns (uint256) {
        if (msg.value != breedingFee) revert InvalidFee();
        if (parentAId == parentBId) revert CannotBreedWithSelf();
        if (ownerOf(parentAId) != msg.sender || ownerOf(parentBId) != msg.sender) revert NotTokenOwner();
        if (_ballLocked[parentAId] || _ballLocked[parentBId]) revert BallIsLocked();

        Ball storage parentA = _balls[parentAId];
        Ball storage parentB = _balls[parentBId];

        if (block.timestamp < parentA.lastBredTimestamp + BREEDING_COOLDOWN) revert BreedingCooldown();
        if (block.timestamp < parentB.lastBredTimestamp + BREEDING_COOLDOWN) revert BreedingCooldown();
        if (parentA.breedCount >= MAX_BREED_COUNT || parentB.breedCount >= MAX_BREED_COUNT) revert MaxBreedsReached();

        parentA.lastBredTimestamp = uint64(block.timestamp);
        parentB.lastBredTimestamp = uint64(block.timestamp);
        parentA.breedCount++;
        parentB.breedCount++;

        _tokenIdCounter.increment();
        uint256 newBallId = _tokenIdCounter.current();

        uint256 randomSeed = _generateRandom(newBallId);

        _balls[newBallId] = Ball({
            mass: _calculateChildTrait(parentA.mass, parentB.mass, randomSeed),
            elasticity: _calculateChildTrait(parentA.elasticity, parentB.elasticity, randomSeed >> 32),
            power: _calculateChildTrait(parentA.power, parentB.power, randomSeed >> 64),
            color: uint32(randomSeed >> 96),
            level: 1, breedCount: 0, xp: 0, totalCollisions: 0, wins: 0, losses: 0, lastBredTimestamp: 0
        });

        _safeMint(msg.sender, newBallId);
        emit BallBred(newBallId, parentAId, parentBId);
        return newBallId;
    }

    //---------------------------------------------------------
    // Staking
    //---------------------------------------------------------

    function stake(uint256 amount) public whenNotPaused {
        if(amount == 0) revert InvalidAmount();
        stakedBXP[msg.sender] += amount;
        bxpToken.transferFrom(msg.sender, address(this), amount);
        emit Staked(msg.sender, amount);
    }

    function unstake(uint256 amount) public whenNotPaused {
        if(amount == 0) revert InvalidAmount();
        if (stakedBXP[msg.sender] < amount) revert InsufficientBalance();
        stakedBXP[msg.sender] -= amount;
        bxpToken.transfer(msg.sender, amount);
        emit Unstaked(msg.sender, amount);
    }

    //---------------------------------------------------------
    // View Functions
    //---------------------------------------------------------

    function getBall(uint256 tokenId) public view returns (Ball memory) {
        if (!_exists(tokenId)) revert TokenNotFound();
        return _balls[tokenId];
    }

    function getListing(uint256 tokenId) public view returns (Listing memory) { return _listings[tokenId]; }

    function getArenaPlayers(uint256 arenaId) public view returns (address[] memory) {
        if (_arenas[arenaId].id == 0) revert ArenaNotFound();
        return _arenas[arenaId].players;
    }

    function isBallLocked(uint256 tokenId) public view returns (bool) { return _ballLocked[tokenId]; }

    function xpRequiredForLevel(uint256 level) public pure returns (uint256) { return _xpRequiredForLevel(level); }

    function getStakingBonusBPS(address player) public view returns (uint256) {
        uint256 bonus = (stakedBXP[player] / (1000 * 10**18)) * 10; // 10 BPS per 1000 BXP
        return bonus > 1000 ? 1000 : bonus; // Cap at 10% (1000 BPS)
    }

    //---------------------------------------------------------
    // Internal & Private Functions
    //---------------------------------------------------------

    function _startGame(uint256 arenaId) internal {
        _arenas[arenaId].state = ArenaState.InProgress;
        emit GameStarted(arenaId);
    }

    function _xpRequiredForLevel(uint256 level) private pure returns (uint256) {
        if (level <= 1) return 0;
        return (level - 1) * 100;
    }

    function _generateRandom(uint256 seed) private returns (uint256) {
        _randomNonce++;
        return uint256(keccak256(abi.encodePacked(block.timestamp, msg.sender, _randomNonce, seed)));
    }

    function _calculateChildTrait(uint32 traitA, uint32 traitB, uint256 randomSeed) private pure returns (uint32) {
        uint256 avgTrait = (uint256(traitA) + uint256(traitB)) / 2;
        uint256 percentage = 90 + (randomSeed % 21); // 90-110
        return uint32((avgTrait * percentage) / 100);
    }

    function _sendValue(address payable recipient, uint256 amount) internal {
        if (amount > 0) {
            (bool success, ) = recipient.call{value: amount}("");
            require(success, "Address: unable to send value, recipient may have reverted");
        }
    }
}

